'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var ln = require( '@stdlib/math/base/special/ln' );
var LN2 = require( '@stdlib/constants/float64/ln-two' );


// MAIN //

/**
* Returns the differential entropy of an anglit distribution with location parameter `mu` and scale parameter `sigma`.
*
* @param {number} mu - location parameter
* @param {number} sigma - scale parameter
* @returns {number} entropy
*
* @example
* var h = entropy( 0.0, 1.0 );
* // returns ~0.307
*
* @example
* var h = entropy( 0.0, 2.0 );
* // returns ~1.000
*
* @example
* var h = entropy( 1.0, 1.0 );
* // returns ~0.307
*
* @example
* var h = entropy( 0.0, 0.5 );
* // returns ~-0.386
*
* @example
* var h = entropy( NaN, 1.0 );
* // returns NaN
*
* @example
* var h = entropy( 0.0, NaN );
* // returns NaN
*
* @example
* var h = entropy( 0.0, -1.0 );
* // returns NaN
*/
function entropy( mu, sigma ) {
	if (
		isnan( mu ) ||
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return NaN;
	}

	return 1.0 - LN2 + ln( sigma );
}


// EXPORTS //

module.exports = entropy;
